<script setup lang="ts">
import {computed} from 'vue'
import type {Run} from '../types'
import MetricChart from './MetricChart.vue'
const props=defineProps<{run:Run}>(),metrics=computed(()=>props.run.metrics)
function series(key:'rps'|'p95'|'users'){return (metrics.value?.series||[]).map(row=>({second:row.second,value:row[key]}))}
</script>
<template><div v-if="metrics" class="performance-report"><div class="metric-grid"><div class="metric-card"><small>有效请求</small><strong>{{metrics.samples}}</strong></div><div class="metric-card"><small>平均吞吐量</small><strong>{{metrics.rps.toFixed(2)}} <small>RPS</small></strong></div><div class="metric-card"><small>P95 响应时间</small><strong>{{metrics.p95.toFixed(1)}} <small>ms</small></strong></div><div class="metric-card"><small>P99 响应时间</small><strong>{{metrics.p99.toFixed(1)}} <small>ms</small></strong></div><div class="metric-card"><small>业务失败率</small><strong>{{metrics.errorRate===null?'—':(metrics.errorRate*100).toFixed(2)+'%'}}</strong></div></div>
<section class="threshold-section"><h3>达标条件</h3><div class="table-panel"><table class="data-table"><thead><tr><th>指标</th><th>实际值</th><th>目标</th><th>结果</th></tr></thead><tbody><tr v-for="c in metrics.thresholds" :key="c.name"><td>{{c.name}}</td><td>{{c.actual===null?'无样本':c.name.includes('失败率')?(c.actual*100).toFixed(2)+'%':Number(c.actual.toFixed(4))}}</td><td>{{c.name==='有效样本数'?'≥':'≤'}} {{c.name.includes('失败率')?(c.limit*100).toFixed(2)+'%':c.limit}}</td><td><span class="status-badge" :class="c.passed?'passed':'failed'">{{c.passed?'满足':'未满足'}}</span></td></tr></tbody></table></div><p v-if="metrics.verdict==='not_evaluated'" class="form-hint">未设置性能条件，本次执行完成，不代表性能达标。</p></section>
<details class="report-section" open><summary>指标趋势</summary><MetricChart title="吞吐量" unit="RPS" color="#28765c" :points="series('rps')"/><MetricChart title="P95 响应时间" unit="ms" color="#c47724" :points="series('p95')"/><MetricChart title="模拟用户数" unit="用户" color="#466db4" :points="series('users')"/></details>
<section class="report-section"><h3>按请求统计</h3><div class="table-panel"><table class="data-table"><thead><tr><th>请求</th><th>样本</th><th>失败</th><th>P95（ms）</th></tr></thead><tbody><tr v-for="e in metrics.endpoints" :key="e.name"><td>{{e.name}}</td><td>{{e.samples}}</td><td>{{e.failed}}</td><td>{{e.p95}}</td></tr></tbody></table></div><p v-for="f in metrics.failures??[]" :key="f.name+f.code+f.message" class="inline-error">{{f.name}} · {{f.code}} · {{f.count}} 次 · {{f.message}}</p></section>
<details class="report-section"><summary>压测资源与统计说明</summary><p class="form-hint">资源为发压容器资源，不代表被测服务资源。预热排除 {{run.configSnapshot?.warmup_seconds??0}} 秒；P95 使用样本排序计算。</p><p v-if="run.resources?.length" class="form-hint">发压容器最近 CPU {{run.resources.at(-1)?.cpuPercent}}%（100% 为一个核），内存 {{run.resources.at(-1)?.memoryMB}} MB。</p></details></div></template>
